import numpy as np
def soft(z, t): return np.sign(z)*np.maximum(np.abs(z)-t, 0)
rng = np.random.default_rng(0)
n, d = 100, 5; X = rng.normal(size=(n, d))
w_true = np.array([3.0, -2.0, 0, 0, 0]); y = X@w_true + rng.normal(0, 0.1, n)
for lam in (0.0, 0.5, 2.0):
    w = np.zeros(d); r = y.copy()
    for _ in range(200):
        w_old = w.copy()
        for j in range(d):
            r += X[:, j]*w[j]; w[j] = soft(X[:, j]@r, lam)/(X[:, j]@X[:, j]); r -= X[:, j]*w[j]
        if np.max(np.abs(w-w_old)) < 1e-6: break
    print(f"λ={lam:>4}: 非零={int((np.abs(w)>1e-3).sum())} w={np.round(w,2)}")

import numpy as np
rng = np.random.default_rng(2); n=2000
d = rng.normal(size=(n,4)); y = (rng.random(n) < 0.01).astype(int)
idx = np.where(y==1)[0]
d[y==1] += 0.8   # 弱可分
def sig(z): z=np.clip(z,-30,30); return 1/(1+np.exp(-z))
w = np.zeros(4);
for _ in range(3000): p=sig(d@w); w += 0.05*d.T@(y-p)
for t in (0.5,0.3,0.1,0.05):
    pred=(p>=t).astype(int); tp=(pred*y).sum(); fp=(pred*(1-y)).sum(); fn=((1-pred)*y).sum()
    P=tp/(tp+fp+1e-9); R=tp/(tp+fn+1e-9); F=2*P*R/(P+R+1e-9)
    print(f"t={t}: acc={((pred==y).mean()):.3f} P={P:.3f} R={R:.3f} F1={F:.3f}")
